<script setup lang="ts">
import TaskTabs from '../components/TaskTabs.vue'
import TaskRequirements from '../components/TaskRequirements.vue'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ChevronDown, ChevronRight, ClipboardList, GitBranch, GripVertical, Plus, Search } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import ProjectMemberSelect from '../components/ProjectMemberSelect.vue'
import Pager from '../components/Pager.vue'
import TaskImportModal from '../components/TaskImportModal.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import TaskInlineCell from '../components/TaskInlineCell.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import { useDraft,useConflict } from '../drafts'
import { all, api, dateLabel, isArchived, messageOf, notify, pickFields, projectName, query, softDelete, taskStatuses, ui } from '../api'
import type { Page, Task } from '../types'
const props=defineProps<{revision:number;initialProject?:string;initialQuery?:string}>();const emit=defineEmits<{changed:[]}>()
const tasks=ref<Task[]>([]),parentTasks=ref<Task[]>([]),total=ref(0),offset=ref(0),project=ref(props.initialProject||''),status=ref(''),search=ref(props.initialQuery||''),error=ref(''),loading=ref(false),open=ref(false),saving=ref(false),formError=ref(''),editing=ref<Task>();const limit=50
const blank=()=>({project_id:project.value||ui.projects.find(p=>p.status!=='archived')?.id||'',parent_id:'',name:'',assignee:'',assignee_member_id:'',plan_start:'',plan_end:'',progress:0,status:'todo',priority:2,estimate_hours:0,description:''});const form=reactive(blank())
const draft=useDraft(()=>`tasks:${editing.value?.id||'new'}`,form,()=>open.value,()=>editing.value?.version);const conflict=useConflict()
const selected=ref<string[]>([]),batchOpen=ref(false),moving=ref<Task>(),moveTarget=ref(''),movePosition=ref('inside'),dragging=ref<Task>(),dropTarget=ref(''),moveError=ref(''),batchError=ref(''),reopenReason=ref(''),reopening=ref(false);const batch=reactive({assignee_on:false,assignee_member_id:'',status_on:false,status:'todo',start_on:false,plan_start:'',end_on:false,plan_end:''})
let pointerDrag:{id:number;source:Task;startX:number;startY:number;handle:HTMLElement;active:boolean}|undefined;let suppressHandleClickUntil=0
const dropPosition=ref('inside')
const importOpen=ref(false),openingTask=ref(false)
const moveChoices=ref<Task[]>([]),collapsed=ref<string[]>([])
const batchProject=computed(()=>{const ids=[...new Set(tasks.value.filter(t=>selected.value.includes(t.id)).map(t=>t.project_id))];return ids.length===1?ids[0]!:''})
function taskPayload(){const payload:Record<string,unknown>={...pickFields(form,blank()),progress:Number(form.progress),priority:Number(form.priority),estimate_hours:Number(form.estimate_hours)};if(derived.value||editing.value?.status==='canceled'){delete payload.assignee_member_id;delete payload.assignee}else if(editing.value&&!editing.value.assignee_member_id&&!form.assignee_member_id&&form.assignee===editing.value.assignee)delete payload.assignee_member_id;return payload}
const filterActive=computed(()=>!!(status.value||search.value.trim()))
const readonly=computed(()=>editing.value?.status==='done'||isArchived(editing.value?.project_id||''))
const derived=computed(()=>!!editing.value&&parentTasks.value.some(t=>t.parent_id===editing.value!.id))
const completeRows=computed(()=>{if(project.value)return tasks.value.map(task=>({task,depth:task.depth||0}));return tasks.value.map(task=>({task,depth:0}))})
const filteredIds=computed(()=>{const matches=new Set<string>();const ancestors=new Set<string>();if(!project.value)return{matches,ancestors};const byId=new Map(tasks.value.map(t=>[t.id,t]));for(const task of tasks.value){const q=search.value.trim().toLocaleLowerCase();if((!status.value||task.status===status.value)&&(!q||[task.name,task.wbs_code,task.assignee,task.description].some(value=>value.toLocaleLowerCase().includes(q)))){matches.add(task.id);let parent=byId.get(task.parent_id);while(parent&&!ancestors.has(parent.id)){ancestors.add(parent.id);parent=byId.get(parent.parent_id)}}}return{matches,ancestors}})
const rows=computed(()=>{if(!project.value)return completeRows.value;const hidden=new Set<string>();const collapsedIds=new Set(collapsed.value);const kept=completeRows.value.filter(({task})=>{if(filterActive.value)return filteredIds.value.matches.has(task.id)||filteredIds.value.ancestors.has(task.id);if(hidden.has(task.parent_id)){hidden.add(task.id);return false}if(collapsedIds.has(task.id))hidden.add(task.id);return true});return kept})
function toggleBranch(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(value=>value!==id):[...collapsed.value,id]}
function rowHasChildren(task:Task){return !!task.has_children}
function inlineReadonly(task:Task,derivedField=false){return !selectable(task)||(derivedField&&rowHasChildren(task))}
async function inlineUpdated(){emit('changed');await load()}
function descendantIds(items:Task[],rootId?:string){const blocked=new Set<string>();if(!rootId)return blocked;const children=new Map<string,string[]>();for(const task of items){const siblings=children.get(task.parent_id);if(siblings)siblings.push(task.id);else children.set(task.parent_id,[task.id])}const stack=[rootId];while(stack.length){const id=stack.pop()!;if(blocked.has(id))continue;blocked.add(id);for(const child of children.get(id)||[])stack.push(child)}return blocked}
const parentChoices=computed(()=>{const blocked=descendantIds(parentTasks.value,editing.value?.id);return parentTasks.value.filter(t=>!blocked.has(t.id)&&t.project_id===form.project_id&&(!['done','canceled'].includes(t.status)||t.id===editing.value?.parent_id))})
const moveTargets=computed(()=>{if(!moving.value)return[];const blocked=descendantIds(moveChoices.value,moving.value.id);return moveChoices.value.filter(task=>!blocked.has(task.id)&&task.project_id===moving.value!.project_id&&!['done','canceled'].includes(task.status))})
async function load(){loading.value=true;error.value='';try{const page=await api<Page<Task>>(project.value?`/api/projects/${project.value}/tree`:`/api/tasks?${query({status:status.value,q:search.value,offset:offset.value,limit})}`);tasks.value=page.items;total.value=page.total;selected.value=[]}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function loadParents(){if(!form.project_id){parentTasks.value=[];return}try{parentTasks.value=(await api<Page<Task>>(`/api/projects/${form.project_id}/tree`)).items}catch(e){formError.value=messageOf(e)}}
onMounted(load);watch(()=>props.revision,load);watch([project,status],()=>{offset.value=0;void load()});watch(()=>props.initialProject,(id)=>{project.value=id||''});watch(()=>props.initialQuery,(q)=>{search.value=q||'';offset.value=0;void load()});watch(()=>form.project_id,()=>{void loadParents()})
async function edit(task?:Task){if(openingTask.value||saving.value||open.value&&!draft.canLeave())return;openingTask.value=true;try{conflict.clear();editing.value=task;Object.assign(form,task?{...pickFields(task,blank()),assignee_member_id:task.assignee_member_id||''}:blank());formError.value='';open.value=true;await loadParents();if(task)form.parent_id=task.parent_id;await draft.reset()}finally{openingTask.value=false}}
async function save(){if(openingTask.value||saving.value||readonly.value)return;saving.value=true;formError.value='';try{await api(editing.value?`/api/tasks/${editing.value.id}`:'/api/tasks',{method:editing.value?'PATCH':'POST',body:JSON.stringify({...taskPayload(),...(editing.value?{version:editing.value.version}:{})})});draft.discard();open.value=false;notify(editing.value?'任务已更新':'任务已创建');emit('changed');await load()}catch(e){formError.value=messageOf(e);if(editing.value)await conflict.capture(e,`/api/tasks/${editing.value.id}`,pickFields(form,blank()))}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as Task;if(!remote)return;draft.persist();editing.value=remote;Object.assign(form,{...pickFields(remote,blank()),assignee_member_id:remote.assignee_member_id||''});conflict.clear();await draft.reset();formError.value='已载入数据库新内容，原修改保留在浏览器草稿中。'}
function keepConflict(){draft.persist();conflict.clear();formError.value='本地内容已保留。请载入新数据后恢复草稿，再核对并保存。'}
function openRequirement(id:string){if(openingTask.value||saving.value||reopening.value||!draft.canLeave())return;open.value=false;location.hash=`#/requirements?id=${encodeURIComponent(id)}`}
function closeEditor(){if(!openingTask.value&&!saving.value&&draft.canLeave())open.value=false}
async function openEntity(id:string){try{await edit(await api<Task>(`/api/tasks/${id}`))}catch(e){notify(messageOf(e),true)}}
async function remove(){if(!editing.value||readonly.value||derived.value)return;try{if(await softDelete('tasks',editing.value,editing.value.name)){draft.discard();open.value=false;emit('changed');await load()}}catch(e){formError.value=messageOf(e)}}
async function reopen(){if(!editing.value||!reopenReason.value.trim())return;reopening.value=true;try{const task=await api<Task>(`/api/tasks/${editing.value.id}/reopen`,{method:'POST',body:JSON.stringify({version:editing.value.version,reason:reopenReason.value,progress:0})});notify('任务已重开为进行中，原因已记录');reopenReason.value='';await edit(task);emit('changed');await load()}catch(e){formError.value=messageOf(e)}finally{reopening.value=false}}
function selectable(task:Task){return !isArchived(task.project_id)&&!['done','canceled'].includes(task.status)}
function toggleAll(event:Event){selected.value=(event.target as HTMLInputElement).checked?rows.value.map(row=>row.task).filter(selectable).map(t=>t.id):[]}
async function saveBatch(){const changes:Record<string,string>={};if(batch.assignee_on){if(!batchProject.value){batchError.value='批量指定负责人需选择同一项目的任务';return}changes.assignee_member_id=batch.assignee_member_id;}if(batch.status_on)changes.status=batch.status;if(batch.start_on)changes.plan_start=batch.plan_start;if(batch.end_on)changes.plan_end=batch.plan_end;if(!Object.keys(changes).length){batchError.value='先勾选需要批量修改的字段';return}saving.value=true;batchError.value='';try{await api('/api/tasks/batch',{method:'POST',body:JSON.stringify({items:tasks.value.filter(t=>selected.value.includes(t.id)).map(t=>({id:t.id,version:t.version})),changes})});batchOpen.value=false;notify('所选任务已在同一事务中更新');emit('changed');await load()}catch(e){batchError.value=messageOf(e)+'；本批次未写入，请核对后重试。'}finally{saving.value=false}}
async function prepareMove(task:Task){moving.value=task;moveTarget.value='';movePosition.value='inside';moveError.value='';try{moveChoices.value=(await api<Page<Task>>(`/api/projects/${task.project_id}/tree`)).items}catch(e){moveError.value=messageOf(e)}}
async function performMove(){if(!moving.value)return;const target=moveChoices.value.find(t=>t.id===moveTarget.value);let parent_id='',before_id='';if(target){if(movePosition.value==='inside')parent_id=target.id;else{parent_id=target.parent_id;if(movePosition.value==='before')before_id=target.id;else{const siblings=moveChoices.value.filter(t=>t.parent_id===target.parent_id&&t.id!==moving.value!.id).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)||a.wbs_code.localeCompare(b.wbs_code,'zh-CN',{numeric:true}));const index=siblings.findIndex(t=>t.id===target.id);before_id=siblings[index+1]?.id||''}}}saving.value=true;moveError.value='';try{await api(`/api/tasks/${moving.value.id}/move`,{method:'POST',body:JSON.stringify({version:moving.value.version,expected_versions:Object.fromEntries(moveChoices.value.map(t=>[t.id,t.version])),parent_id,...(before_id?{before_id}:{})})});moving.value=undefined;notify('任务位置已更新，WBS 编码已重算');emit('changed');await load()}catch(e){moveError.value=messageOf(e)}finally{saving.value=false}}
function dragStart(event:DragEvent,task:Task){if(pointerDrag){event.preventDefault();return}if(!selectable(task)){event.preventDefault();return}dragging.value=task;event.dataTransfer?.setData('text/plain',task.id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
async function drop(event:DragEvent,target:Task){event.preventDefault();const source=dragging.value;dragging.value=undefined;dropTarget.value='';if(!source||source.id===target.id)return;if(source.project_id!==target.project_id){notify('只能在同一项目内移动任务',true);return}const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();const ratio=(event.clientY-rect.top)/rect.height;await prepareMove(source);moveTarget.value=target.id;movePosition.value=ratio<.3?'before':ratio>.7?'after':'inside'}
function pointerTarget(x:number,y:number){const element=document.elementFromPoint(x,y)?.closest<HTMLElement>('[data-task-id]');const task=tasks.value.find(item=>item.id===element?.dataset.taskId);if(!element||!task)return;const rect=element.getBoundingClientRect();const ratio=(y-rect.top)/rect.height;return{task,position:ratio<.3?'before':ratio>.7?'after':'inside'}}
function pointerStart(event:PointerEvent,task:Task){if(event.button!==0||!event.isPrimary||!selectable(task))return;event.preventDefault();const handle=event.currentTarget as HTMLElement;pointerDrag={id:event.pointerId,source:task,startX:event.clientX,startY:event.clientY,handle,active:false};handle.setPointerCapture(event.pointerId)}
function pointerMove(event:PointerEvent){if(!pointerDrag||event.pointerId!==pointerDrag.id)return;if(!pointerDrag.active&&Math.hypot(event.clientX-pointerDrag.startX,event.clientY-pointerDrag.startY)<6)return;event.preventDefault();pointerDrag.active=true;dragging.value=pointerDrag.source;const target=pointerTarget(event.clientX,event.clientY);dropTarget.value=target&&target.task.id!==pointerDrag.source.id&&target.task.project_id===pointerDrag.source.project_id?target.task.id:'';dropPosition.value=target?.position||'inside'}
function releasePointer(){const drag=pointerDrag;pointerDrag=undefined;dragging.value=undefined;dropTarget.value='';if(drag?.handle.hasPointerCapture(drag.id))drag.handle.releasePointerCapture(drag.id)}
async function pointerEnd(event:PointerEvent){const drag=pointerDrag;if(!drag||event.pointerId!==drag.id)return;const target=pointerTarget(event.clientX,event.clientY);releasePointer();if(!drag.active){suppressHandleClickUntil=Date.now()+350;await prepareMove(drag.source);return}event.preventDefault();suppressHandleClickUntil=Date.now()+500;if(!target||target.task.id===drag.source.id)return;if(target.task.project_id!==drag.source.project_id){notify('只能在同一项目内移动任务',true);return}await prepareMove(drag.source);moveTarget.value=target.task.id;movePosition.value=target.position}
function pointerCancel(){if(pointerDrag?.active)suppressHandleClickUntil=Date.now()+500;releasePointer()}
function handleClick(task:Task){if(Date.now()<suppressHandleClickUntil)return;void prepareMove(task)}
defineExpose({openEntity,canLeave:()=>!openingTask.value&&!saving.value&&!reopening.value&&(!open.value||draft.canLeave())})
function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>任务与 WBS</h1><p class="page-description">把工作逐层拆开，进度和责任落到每一项。</p></div><div class="row-actions"><button class="button subtle" :disabled="!ui.projects.some(p=>p.status!=='archived')" @click="importOpen=true">导入 Excel</button><button class="button primary" :disabled="!ui.projects.some(p=>p.status!=='archived')" @click="edit()"><Plus :size="18"/>新增任务</button></div></div><TaskTabs active="tasks"/><form class="filter-bar" @submit.prevent="offset=0;load()"><select v-model="project" aria-label="筛选项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}{{p.status==='archived'?'（已归档）':''}}</option></select><select v-model="status" aria-label="任务状态"><option value="">全部状态</option><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索任务" aria-label="搜索任务"/></div><button type="submit" class="button subtle">查询</button></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div v-if="selected.length" class="selection-bar"><strong>已选 {{selected.length}} 项</strong><button class="button small primary" @click="batchOpen=true;batchError=''">批量修改</button><button class="text-button" @click="selected=[]">取消选择</button></div><div class="surface"><div class="table-caption"><span><GitBranch :size="15"/>WBS 层级视图</span><span class="muted">{{total}} 项任务<span v-if="project"> · 完整项目树，当前显示 {{rows.length}} 项{{filterActive?'（保留匹配项祖先）':''}}</span><span v-else> · 全部项目分页列表</span></span></div><p v-if="loading" class="loading-message">正在读取任务…</p><div v-else-if="!rows.length" class="empty-state"><ClipboardList :size="38"/><h2>{{ui.projects.length?'还没有符合条件的任务':'先建立一个项目'}}</h2><p>{{ui.projects.length?'从一个明确的工作项开始，逐步拆成子任务。':'任务需要关联项目。前往「项目」新建项目后再分解工作。'}}</p><button v-if="ui.projects.some(p=>p.status!=='archived')" class="button primary" @click="edit()">新增任务</button></div><div v-else class="table-scroll"><table class="task-table"><thead><tr><th class="check-cell"><input type="checkbox" aria-label="选择本页可编辑任务" @change="toggleAll"/></th><th>{{project?'完整任务树':'任务 / 项目'}}</th><th>负责人</th><th>计划结束</th><th>进度</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="{task,depth} in rows" :key="task.id" :data-task-id="task.id" :class="{'drop-active':dropTarget===task.id,'drop-before':dropTarget===task.id&&dropPosition==='before','drop-after':dropTarget===task.id&&dropPosition==='after'}" @dragover.prevent="dropTarget=task.id" @dragleave="dropTarget=''" @drop="drop($event,task)" @dragend="dragging=undefined;dropTarget=''"><td class="check-cell"><input v-model="selected" :value="task.id" type="checkbox" :disabled="!selectable(task)" :aria-label="`选择任务 ${task.name}`"/></td><td><div class="wbs-title" :style="{paddingLeft:`${depth*20}px`}"><button v-if="selectable(task)" class="drag-handle" draggable="true" :aria-label="`拖动任务 ${task.name}，或使用行末移动按钮`" title="拖动调整位置；也可用移动按钮" @dragstart="dragStart($event,task)" @dragend="dragging=undefined;dropTarget=''" @pointerdown="pointerStart($event,task)" @pointermove="pointerMove" @pointerup="pointerEnd" @pointercancel="pointerCancel" @click="handleClick(task)"><GripVertical :size="14"/></button><button v-if="project&&rowHasChildren(task)" class="tree-toggle" :disabled="filterActive" :aria-label="`${collapsed.includes(task.id)?'展开':'折叠'} ${task.name}`" :aria-expanded="filterActive||!collapsed.includes(task.id)" @click="toggleBranch(task.id)"><ChevronRight v-if="!filterActive&&collapsed.includes(task.id)" :size="14"/><ChevronDown v-else :size="14"/></button><span v-else class="tree-toggle-spacer"/><span class="wbs-code">{{task.wbs_code||'—'}}</span><div><TaskInlineCell :task="task" field="name" label="任务名称" :readonly="inlineReadonly(task)" @updated="inlineUpdated"><button class="table-title" @click="edit(task)">{{task.name}}</button></TaskInlineCell><small v-if="project&&filterActive&&!filteredIds.matches.has(task.id)" class="ancestor-label">保留上级路径</small><small v-if="!project">{{projectName(task.project_id)}}</small></div></div></td><td><TaskInlineCell :task="task" field="assignee" label="负责人" :readonly="inlineReadonly(task)||rowHasChildren(task)" @updated="inlineUpdated">{{task.assignee||'未指定'}}</TaskInlineCell></td><td :class="{overdue:task.overdue}"><TaskInlineCell :task="task" field="plan_end" label="计划截止日期" :readonly="inlineReadonly(task)" @updated="inlineUpdated">{{dateLabel(task.plan_end)}}</TaskInlineCell><small v-if="task.overdue">已逾期</small></td><td><TaskInlineCell :task="task" field="progress" label="叶子进度" :readonly="inlineReadonly(task,true)" @updated="inlineUpdated"><div class="progress-label"><div class="progress-track"><i :style="{width:`${task.progress}%`}"/></div><span>{{task.progress}}%</span></div></TaskInlineCell></td><td><TaskInlineCell :task="task" field="status" label="任务状态" :readonly="inlineReadonly(task,true)" @updated="inlineUpdated"><span class="badge" :class="task.status">{{taskStatuses[task.status]}}</span></TaskInlineCell></td><td class="right"><div class="row-actions"><button v-if="selectable(task)" class="text-button" @click="prepareMove(task)">移动</button><button class="text-button" @click="edit(task)">{{task.status==='done'||isArchived(task.project_id)?'查看':'编辑'}}</button></div></td></tr></tbody></table></div><Pager v-if="!project" :offset="offset" :limit="limit" :total="total" @change="page"/></div><Modal :open="open" :title="readonly?'任务详情':editing?'编辑任务':'新增任务'" wide @close="closeEditor"><form class="modal-body" @submit.prevent="save"><DraftNotice :value="draft.available.value" :error="draft.storageError.value" :values="draft.values.value" @select="draft.select" :recovery="draft.recovery.value" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @restore="draft.restore" @discard="draft.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="keepConflict" @reload="reloadConflict"/><fieldset :disabled="readonly||saving||openingTask"><label>任务名称 <span class="required">*</span><input v-model="form.name" required maxlength="200" autofocus/></label><div class="form-row"><label>所属项目 <span class="required">*</span><select v-model="form.project_id" required :disabled="!!editing" @change="form.parent_id='';form.assignee='';form.assignee_member_id=''"><option v-for="p in ui.projects.filter(p=>p.status!=='archived'||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>上级任务<select v-model="form.parent_id"><option value="">无，作为顶层任务</option><option v-for="task in parentChoices" :key="task.id" :value="task.id">{{task.wbs_code}} {{task.name}}</option></select></label></div><div class="form-row"><label>负责人<ProjectMemberSelect v-model="form.assignee_member_id" :project-id="form.project_id" stable :legacy-name="form.assignee" :disabled="derived||readonly||['done','canceled'].includes(form.status)" @chosen="form.assignee=$event?.name||''"/><span v-if="derived" class="input-hint">父任务不指派成员，请分配叶子任务。</span></label><label>优先级<select v-model.number="form.priority"><option :value="1">高</option><option :value="2">中</option><option :value="3">低</option></select></label></div><div class="form-row"><label>计划开始<input v-model="form.plan_start" type="date"/></label><label>计划结束<input v-model="form.plan_end" type="date" :min="form.plan_start||undefined"/></label></div><div class="form-row"><label>任务状态<select v-model="form.status" :disabled="derived"><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select></label><label>完成进度 %<input v-model.number="form.progress" :disabled="derived" type="number" min="0" max="100" step="1" required/></label></div><p v-if="editing" class="input-hint actual-time-note">实际已记工时：{{editing.actual_hours||0}} 小时（仅汇总工时条目，不能在任务中直接修改）</p><label>预计工时（小时）<input v-model.number="form.estimate_hours" :disabled="derived" type="number" min="0" step="0.5"/></label><label>任务说明<textarea v-model="form.description" rows="3"/></label></fieldset><div v-if="editing?.status==='done'&&!derived&&!isArchived(editing.project_id)" class="reopen-box"><label>重开原因<input v-model="reopenReason" placeholder="说明为什么重新打开此任务"/></label><button type="button" class="button small" :disabled="reopening||!reopenReason.trim()" @click="reopen">重开为进行中</button></div><TaskRequirements v-if="editing" :task-id="editing.id" :revision="props.revision+editing.version" :disabled="saving||reopening||openingTask" @open="openRequirement"/><HistoryPanel v-if="editing" kind="tasks" :id="editing.id" :revision="editing.version"/><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span class="muted">{{readonly?'已完成或已归档的任务只读':form.status==='done'?'保存为已完成后，任务进入只读状态':derived?'父任务状态、进度和工时由子任务汇总':'调整上级任务即可移动层级'}}</span><button v-if="editing&&!readonly&&!derived&&editing.status!=='canceled'" type="button" class="button subtle small" @click="remove">移入回收站</button><button v-if="!readonly" type="submit" class="button primary" :disabled="saving||openingTask">{{saving?'正在保存…':'保存任务'}}</button></div></form></Modal><Modal :open="!!moving" title="移动任务与调整顺序" @close="!saving&&(moving=undefined)"><form class="modal-body" @submit.prevent="performMove"><p class="input-hint">{{moving?.name}} · 仅在同一项目内移动，保存后重算 WBS。</p><label>参照任务<select v-model="moveTarget"><option value="">项目顶层末尾</option><option v-for="task in moveTargets" :key="task.id" :value="task.id">{{task.wbs_code}} {{task.name}}</option></select></label><label v-if="moveTarget">放置位置<select v-model="movePosition"><option value="before">参照任务上方（同级）</option><option value="inside">参照任务内部（子任务末尾）</option><option value="after">参照任务下方（同级）</option></select></label><p v-if="moveError" class="form-error">{{moveError}}</p><div class="modal-footer"><button class="button primary" :disabled="saving">确认移动</button></div></form></Modal><Modal :open="batchOpen" title="批量修改任务" @close="!saving&&(batchOpen=false)"><form class="modal-body" @submit.prevent="saveBatch"><p class="input-hint">本批次 {{selected.length}} 项任务。仅修改勾选字段，任意一项失败则整批不写入。</p><label class="checkbox-label"><input v-model="batch.assignee_on" type="checkbox" :disabled="!batchProject"/>修改负责人</label><ProjectMemberSelect v-if="batch.assignee_on" v-model="batch.assignee_member_id" :project-id="batchProject" stable placeholder="未指定（清空负责人）"/><p v-if="!batchProject" class="input-hint">先筛选同一项目的任务，再批量选择负责人。</p><label class="checkbox-label"><input v-model="batch.status_on" type="checkbox"/>修改状态</label><select v-if="batch.status_on" v-model="batch.status" aria-label="批量状态"><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select><label class="checkbox-label"><input v-model="batch.start_on" type="checkbox"/>修改计划开始</label><input v-if="batch.start_on" v-model="batch.plan_start" type="date" aria-label="批量开始日期"/><label class="checkbox-label"><input v-model="batch.end_on" type="checkbox"/>修改计划结束</label><input v-if="batch.end_on" v-model="batch.plan_end" type="date" aria-label="批量结束日期"/><p v-if="batchError" class="form-error" role="alert">{{batchError}}</p><div class="modal-footer"><button class="button primary" :disabled="saving">{{saving?'正在保存…':'应用批量修改'}}</button></div></form></Modal><TaskImportModal :open="importOpen" :project-id="project" @close="importOpen=false" @imported="emit('changed');load()"/></template>
